import * as React from "react";
import { DefaultVideoPlayerProps } from "./plasmic/sayban/PlasmicVideoPlayer";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import { useVideoFullscreen } from "@/lib/useVideoFullscreen";
import styles from "./VideoPlayer.module.css";

export interface VideoPlayerProps extends DefaultVideoPlayerProps {}

/**
 * Self-contained replacement for the generated PlasmicVideoPlayer.
 *
 * The generated player rendered `<video controls={false}>` under a full-size
 * absolute overlay and drove playback from an injected <script> that resolved
 * its target with `document.querySelector('.my-video-player video')` and
 * `document.getElementById('play-btn' | 'pause-btn' | ...)`. That class and
 * those ids are hardcoded on every instance, and the panel mounts several
 * players at once (EditStaffs twice, each with an upload preview plus the saved
 * video), so every script after the first bound its buttons to the *first*
 * matching element in the document. Pressing play on the visible player started
 * a different, source-less video — which is why a saved nurse video never
 * played. Native controls remove that whole class of bug and bring keyboard
 * support, buffering UI and fullscreen with it.
 */
function VideoPlayer_(props: VideoPlayerProps, ref: HTMLElementRefOf<"div">) {
  const { link, className } = props;
  const src = typeof link === "string" ? link.trim() : "";

  const containerRef = React.useRef<HTMLDivElement | null>(null);
  const videoRef = React.useRef<HTMLVideoElement | null>(null);
  const [failed, setFailed] = React.useState(false);

  const { isFullscreen, toggle } = useVideoFullscreen(containerRef, videoRef);

  React.useEffect(() => {
    setFailed(false);
    const el = videoRef.current;
    if (!el) return;

    // The media element starts loading from the server-rendered markup, so a
    // fast failure can fire before React attaches its handler. Re-check the
    // element's own error state on mount and listen natively as well.
    const onError = () => setFailed(true);
    if (el.error) setFailed(true);
    el.addEventListener("error", onError);
    return () => el.removeEventListener("error", onError);
  }, [src]);

  const setContainer = (node: HTMLDivElement | null) => {
    containerRef.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
  };

  // A `<video>` with no src renders as a collapsed black sliver, which reads as
  // a broken player; say what is going on instead.
  if (!src) {
    return (
      <div ref={setContainer} className={[styles.placeholder, className].filter(Boolean).join(" ")}>
        ویدیویی برای نمایش وجود ندارد.
      </div>
    );
  }

  if (failed) {
    return (
      <div ref={setContainer} className={[styles.placeholder, className].filter(Boolean).join(" ")}>
        ویدیو بارگذاری نشد. اتصال خود را بررسی کنید یا دوباره تلاش کنید.
      </div>
    );
  }

  return (
    <div
      ref={setContainer}
      className={[styles.root, className].filter(Boolean).join(" ")}
    >
      <video
        // Keyed by src so a changed source remounts the element rather than
        // leaving a previously errored media element in place.
        key={src}
        ref={videoRef}
        className={styles.video}
        src={src}
        controls
        playsInline
        preload="metadata"
        onError={() => setFailed(true)}
      />

      <button
        type="button"
        className={styles.fullscreenButton}
        onClick={toggle}
        aria-label={isFullscreen ? "خروج از تمام‌صفحه" : "نمایش تمام‌صفحه"}
        title={isFullscreen ? "خروج از تمام‌صفحه" : "نمایش تمام‌صفحه"}
      >
        {isFullscreen ? (
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
            <path d="M9 3H5a2 2 0 0 0-2 2v4M15 3h4a2 2 0 0 1 2 2v4M9 21H5a2 2 0 0 1-2-2v-4M15 21h4a2 2 0 0 0 2-2v-4" />
          </svg>
        ) : (
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
            <path d="M3 9V5a2 2 0 0 1 2-2h4M21 9V5a2 2 0 0 0-2-2h-4M3 15v4a2 2 0 0 0 2 2h4M21 15v4a2 2 0 0 1-2 2h-4" />
          </svg>
        )}
      </button>
    </div>
  );
}

const VideoPlayer = React.forwardRef(VideoPlayer_);
export default VideoPlayer;
